<script setup lang="ts">
import {computed,onMounted,ref,watch} from 'vue'
import {useRoute} from 'vue-router'
import {errorMessage,formatTime} from '@/features/versions/api'
import ArgumentGraph from '@/features/annotation/ArgumentGraph.vue'
import {loadWorkspace,read,useTeachingMutation,utc,type Workspace,type Row} from './api'
const props=defineProps<{page:'home'|'assignment'|'standard'|'results'|'compare'}>()
const route=useRoute(),data=ref<Workspace>(),loading=ref(false),loadError=ref(''),standard=ref<Row>(),result=ref<Row>(),results=ref<Row[]>([]),errorCounts=ref<Row>({})
const {busy,pending,error,mutate}=useTeachingMutation();const blocked=computed(()=>busy.value||pending.value)
const courseName=ref(''),className=ref(''),studentIds=ref<string[]>([]),grantFinal=ref(''),grantTeacher=ref(''),grantId=ref(''),standardName=ref(''),stdId=ref(''),revisionReason=ref(''),feedback=ref('')
const assignmentName=ref(''),courseId=ref(''),selectedDraft=ref(''),exerciseMode=ref('RELATION_GUIDED'),exerciseType=ref('GRAPH_COMPARE'),due=ref(''),opens=ref(''),maxAttempts=ref(2)
const title=computed(()=>({home:'法律论证标注 · 教学',assignment:'创建教学作业',standard:'标准标注样例',results:'学生结果总览',compare:'作答比对与反馈'}[props.page]))
const published=computed(()=>data.value?.standards.filter(n=>n.status==='PUBLISHED')||[])
async function load(){loading.value=true;loadError.value='';try{data.value=await loadWorkspace();if(props.page==='results'||props.page==='compare'){const r=await read('/results');results.value=r.items;errorCounts.value=r.specialistErrorCounts||{}}if(props.page==='standard'&&data.value.teacherMode){const id=typeof route.query.id==='string'?route.query.id:stdId.value;if(id)await showStandard(id)}if(props.page==='compare'&&typeof route.query.id==='string')await showResult(route.query.id)}catch(e){loadError.value=errorMessage(e)}finally{loading.value=false}}
async function showStandard(id:string){try{stdId.value=id;standard.value=await read(`/standards/${id}`)}catch(e){loadError.value=errorMessage(e)}}
async function showResult(id:string){try{result.value=await read(`/results/${id}`)}catch(e){loadError.value=errorMessage(e)}}
async function action(path:string,body:Row,version=0,method:'POST'|'PATCH'='POST'){const r=await mutate(path,body,version,method);if(r)await load();return r}
async function createCourse(){const n=await action('/courses',{name:courseName.value,className:className.value,studentUserIds:studentIds.value});if(n){courseName.value='';className.value='';studentIds.value=[]}}
async function createStandard(){const n=await action('/standards',{sourceGrantId:grantId.value,name:standardName.value});if(n)await showStandard(n.id)}
async function revise(){if(!standard.value)return;const n=await action(`/standards/${standard.value.standard.id}/revisions`,{sourceGrantId:standard.value.standard.sourceGrantId,reason:revisionReason.value});if(n)await showStandard(n.id)}
async function createAssignment(){try{const n=await action('/assignments',{name:assignmentName.value,courseId:courseId.value,standardId:stdId.value,exerciseMode:exerciseMode.value,exerciseType:exerciseType.value,dueAt:utc(due.value)});if(n)selectedDraft.value=n.id}catch(e){loadError.value=errorMessage(e)}}
async function publish(){try{const a=data.value?.assignments.find(x=>x.id===selectedDraft.value);if(a)await action(`/assignments/${a.id}/publish`,{maxAttempts:maxAttempts.value,answerOpensAt:utc(opens.value)},a.recordVersion)}catch(e){loadError.value=errorMessage(e)}}
async function saveFeedback(){if(!result.value)return;const n=await action(`/results/${result.value.id}/feedback`,{comment:feedback.value,itemFeedback:[]});if(n){feedback.value='';await showResult(result.value.id)}}
function changeDraft(){const a=data.value?.assignments.find(x=>x.id===selectedDraft.value);if(a){assignmentName.value=a.name;due.value=new Date(a.dueAt).toLocaleString('sv-SE').slice(0,16).replace(' ','T')}}
watch(()=>[props.page,route.query.id],()=>{standard.value=undefined;result.value=undefined;load()})
onMounted(load)
</script>
<template>
 <div class="page-head between"><div><div class="eyebrow">TEACHING</div><h1 class="t-h1">{{title}}</h1><p class="t-sm muted">课程范围独立授权；标准、每次作答和评分规则固定留存。</p></div><div class="row"><router-link class="btn btn-secondary" to="/teaching">教学首页</router-link><router-link v-if="data?.teacherMode" class="btn btn-primary" to="/assignment-create">＋ 发布作业</router-link><router-link v-if="data?.teacherMode||data?.studentMode" class="btn btn-secondary" to="/student-results">结果总览</router-link></div></div>
 <div class="note warn boundary">D 分支教学试行。关系/图专项使用 C 的评分规则；完整案例的边界、要素评分和综合总分尚未确认，保持空值。成绩及标准样例归档导出待接入。</div>
 <div v-if="error||loadError" class="note danger boundary" role="alert">{{error||loadError}} <button class="btn btn-sm" @click="load">刷新</button></div>
 <button v-if="pending&&!busy" class="btn btn-primary boundary" @click="action('',{})">沿原请求重试</button>
 <div v-if="loading&&!data" class="card card-body">正在读取教学工作区…</div>
 <fieldset v-if="data" :disabled="blocked" class="fields">
 <template v-if="page==='home'">
  <section v-if="data.creatorMode" class="card boundary"><div class="card-head"><b>授权教学来源</b></div><div class="card-body stack-3"><p class="t-sm muted">只有本人任务的已入库成果可明确授权给教师；原科研内容保持只读。</p><select class="select" aria-label="授权来源最终版" v-model="grantFinal"><option value="">选择已入库成果</option><option v-for="s in data.sources" :key="s.finalVersionId" :value="s.finalVersionId">{{s.title}} · F{{s.versionNumber}}</option></select><select class="select" aria-label="授权教师" v-model="grantTeacher"><option value="">选择教师</option><option v-for="t in data.teachers" :key="t.id" :value="t.id">{{t.displayName}}</option></select><button class="btn btn-primary" :disabled="!grantFinal||!grantTeacher" @click="action('/source-grants',{finalVersionId:grantFinal,teacherUserId:grantTeacher})">保存教学来源授权</button><div v-for="g in data.sourceGrants" :key="g.id" class="between"><span>{{g.title}} · {{g.status}}</span><button v-if="g.status==='ACTIVE'" class="btn btn-sm" @click="action(`/source-grants/${g.id}/revoke`,{reason:'创建者撤销后续新教学使用'},g.recordVersion)">撤销后续使用</button></div></div></section>
  <section v-if="data.teacherMode" class="grid-2 teaching-body"><div class="stack-5"><div class="card"><div class="card-head"><b>课程与班级</b></div><div class="card-body stack-3"><div v-for="c in data.courses" :key="c.id" class="panel"><b>{{c.name}} · {{c.class.name}}</b><p class="t-xs muted">{{c.status}} · {{c.students.filter((s:Row)=>s.status==='ACTIVE').length}} 名有效学生</p><button v-if="c.status==='DRAFT'" class="btn btn-sm btn-primary" @click="action(`/courses/${c.id}/activate`,{confirmed:true},c.recordVersion)">开课</button><details><summary>班级成员</summary><div v-for="s in c.students" :key="s.id" class="between"><span>{{s.displayName}} · {{s.status}}</span><button v-if="s.status==='ACTIVE'" class="btn btn-sm" @click="action(`/members/${s.id}/deactivate`,{reason:'教师停用班级成员'},s.recordVersion)">停用</button></div></details></div><p v-if="!data.courses.length" class="muted">尚未创建课程班级。</p></div></div><div class="card"><div class="card-head"><b>已发布作业 / 练习任务</b></div><div class="card-body"><div v-for="a in data.assignments" :key="a.id" class="between item"><span>{{a.name}} · {{a.status}} · {{a.exerciseMode==='RELATION_GUIDED'?'给定命题专项':'独立完整案例'}}</span><router-link class="btn btn-sm" to="/student-results">查看提交</router-link></div><p v-if="!data.assignments.length" class="muted">暂无作业。</p></div></div></div><div class="stack-5"><div class="card"><div class="card-head"><b>新建课程班级</b></div><div class="card-body stack-3"><label>课程名称<input class="input" v-model="courseName"></label><label>班级名称<input class="input" v-model="className"></label><label v-for="s in data.students" :key="s.id"><input type="checkbox" v-model="studentIds" :value="s.id"> {{s.displayName}}</label><button class="btn btn-primary" :disabled="!courseName||!className" @click="createCourse">保存课程草稿</button></div></div><div class="card"><div class="card-head"><b>标准样例</b></div><div class="card-body"><p>{{data.standards.filter(s=>s.status==='PUBLISHED').length}} 个已发布版本</p><router-link class="btn btn-secondary" to="/teaching-standard">管理标准标注</router-link></div></div></div></section>
  <section v-if="data.studentMode" class="card"><div class="card-head"><b>本人班级作业</b></div><div class="card-body"><div v-for="a in data.assignments" :key="a.id" class="between item"><div><b>{{a.name}}</b><p class="t-xs muted">截止 {{formatTime(a.dueAt)}} · 最多 {{a.maxAttempts}} 次 · {{a.exerciseMode==='RELATION_GUIDED'?'给定命题关系专项':'独立完整案例'}}</p></div><router-link class="btn btn-primary" :to="`/student-annotate/${a.id}`">进入作答</router-link></div><p v-if="!data.assignments.length" class="muted">暂无本人班级已发布作业。</p></div></section>
 </template>
 <section v-if="page==='assignment'" class="card boundary"><div class="card-head"><b>作业设置与授权范围</b></div><div v-if="data.teacherMode" class="card-body stack-3"><label>作业名称<input class="input" v-model="assignmentName"></label><label>所属课程班级<select class="select" v-model="courseId"><option value="">选择课程班级</option><option v-for="c in data.courses" :key="c.id" :value="c.id">{{c.name}} · {{c.class.name}} · {{c.status}}</option></select></label><label>已发布标准版本<select class="select" v-model="stdId"><option value="">选择固定标准版本</option><option v-for="s in published" :key="s.id" :value="s.id">{{s.name}} · 第 {{s.versionNumber}} 版</option></select></label><label>练习模式<select class="select" v-model="exerciseMode"><option value="RELATION_GUIDED">给定命题的关系专项</option><option value="FULL_CASE">独立完整案例（分项规则待确认）</option></select></label><label>关系 / 图专项类型<select class="select" v-model="exerciseType" :disabled="exerciseMode==='FULL_CASE'"><option v-for="t in data.exerciseTypes" :key="t.code" :value="t.code">{{t.label}}</option></select></label><label>截止时间（本地时间）<input class="input" type="datetime-local" v-model="due"></label><button class="btn btn-primary" :disabled="!assignmentName||!courseId||!stdId||!due" @click="createAssignment">保存作业草稿</button><hr><label>待发布作业<select class="select" v-model="selectedDraft" @change="changeDraft"><option value="">选择草稿作业</option><option v-for="a in data.assignments.filter(x=>x.status==='DRAFT')" :key="a.id" :value="a.id">{{a.name}}</option></select></label><label>最多作答次数<input class="input" type="number" min="1" max="10" v-model.number="maxAttempts"></label><label>答案开放时间（本地时间）<input class="input" type="datetime-local" v-model="opens"></label><p class="t-sm muted">发布后固定标准与评分版本。学生须先提交，且到达开放时间，才能查看标准、得分差异及教师反馈。</p><button class="btn btn-primary" :disabled="!selectedDraft||!opens" @click="publish">发布到所属班级</button></div><div v-else class="card-body muted">仅所属课程教师可发布作业。</div></section>
 <template v-if="page==='standard'"><div v-if="!data.teacherMode" class="note warn">标准由所属教师管理；学生请在本人结果开放后查看对应版本。</div><section v-else class="grid-2 teaching-body boundary"><div class="card"><div class="card-head"><b>标准版本</b></div><div class="card-body stack-3"><div v-for="s in data.standards" :key="s.id" class="between"><button class="btn btn-sm" @click="showStandard(s.id)">{{s.name}} · v{{s.versionNumber}}</button><span>{{s.status}}</span></div><label>有效教学来源<select class="select" v-model="grantId"><option value="">选择已获授权的成果</option><option v-for="g in data.sourceGrants.filter(x=>x.status==='ACTIVE')" :key="g.id" :value="g.id">{{g.title}}</option></select></label><label>标准名称<input class="input" v-model="standardName"></label><button class="btn btn-primary" :disabled="!grantId||!standardName" @click="createStandard">建立独立标准草稿</button><p class="t-xs muted">没有来源时，须先由成果任务创建者授权给本教师。</p></div></div><div v-if="standard" class="card"><div class="card-head"><b>{{standard.standard.name}} · v{{standard.standard.versionNumber}}</b></div><div class="card-body stack-3"><p>{{standard.standard.status}}</p><label>发布 / 修订说明<input class="input" v-model="revisionReason"></label><button v-if="standard.standard.status==='DRAFT'" class="btn btn-primary" :disabled="!revisionReason" @click="action(`/standards/${standard.standard.id}/publish`,{reason:revisionReason},standard.standard.recordVersion).then(n=>n&&showStandard(n.id))">发布此标准版本</button><button v-else class="btn btn-secondary" :disabled="!revisionReason" @click="revise">追加新修订草稿</button><p class="t-xs muted digest">标准摘要 {{standard.standard.contentDigest}}</p><p class="source-text">{{standard.snapshot.scopeText}}</p><div class="tbl-wrap"><table class="tbl"><thead><tr><th>序号</th><th>文本</th><th>类型</th></tr></thead><tbody><tr v-for="e in standard.snapshot.elements" :key="e.id"><td>{{e.displayNo||'非命题'}}</td><td>{{e.text}}</td><td>{{e.labelCode}}</td></tr></tbody></table></div><b>标准论证图示</b><ArgumentGraph :nodes="standard.snapshot.graph.nodes" :edges="standard.snapshot.graph.edges" :editable="false"/></div></div></section></template>
 <section v-if="page==='results'" class="card boundary"><div class="card-head between"><b>提交与成绩记录</b><button class="btn btn-sm" disabled>成绩归档导出待接入</button></div><div class="tbl-wrap"><table class="tbl"><thead><tr><th>作业</th><th>学生 / 次数</th><th>提交时间</th><th>关系/图专项分</th><th>综合总分</th><th>操作</th></tr></thead><tbody><tr v-for="r in results" :key="r.id"><td>{{r.assignmentName}}</td><td>{{r.studentName}} · 第 {{r.attemptNumber}} 次</td><td>{{formatTime(r.submittedAt)}}</td><td>{{r.scoreAvailability==='HELD'?'未到开放条件':r.grading?.relationSpecialistScore??'待确认口径'}}</td><td>—</td><td><router-link class="btn btn-sm" :to="`/student-compare?id=${r.id}`">比对 / 反馈</router-link></td></tr><tr v-if="!results.length"><td colspan="6" class="empty muted">暂无权限范围内的提交。</td></tr></tbody></table></div><div v-if="data.teacherMode" class="card-body"><b>关系 / 图专项高频错误</b><p v-for="(count,code) in errorCounts" :key="code">{{code}}：{{count}}</p><p v-if="!Object.keys(errorCounts).length" class="muted">当前没有专项错误统计。此统计不作为课程总分。</p></div></section>
 <template v-if="page==='compare'"><section v-if="!result" class="card card-body">请从结果总览选择一次作答。<router-link to="/student-results">返回结果总览</router-link></section><section v-else class="stack-5 boundary"><div class="card card-body"><b>{{result.assignmentName}} · {{result.studentName}} · 第 {{result.attemptNumber}} 次</b><p v-if="result.scoreAvailability==='HELD'" class="note warn">结果已保存。标准、专项得分差异及教师反馈须到 {{formatTime(result.answerOpensAt)}} 后开放。</p><p v-else>关系 / 图专项：{{result.grading?.relationSpecialistScore??'评分口径待确认'}} · 综合总分：—</p><p class="t-xs muted">给定命题专项不评学生要素类型；完整案例的边界/要素口径未确认时，以下只展示，不判定对错。</p></div><div class="grid-2"><div class="card"><div class="card-head"><b>本人命题与已保存图</b></div><div class="card-body"><p v-for="e in result.myElements" :key="e.id">{{e.displayNo||'非命题'}} · {{e.labelCode}} · {{e.text}}</p><ArgumentGraph v-if="result.myGraph" :nodes="result.myGraph.nodes" :edges="result.myGraph.edges" :editable="false"/></div></div><div v-if="result.standardSnapshot" class="card"><div class="card-head"><b>本次固定标准</b></div><div class="card-body"><p v-for="e in result.standardSnapshot.elements" :key="e.id">{{e.displayNo||'非命题'}} · {{e.labelCode}} · {{e.text}}</p><ArgumentGraph :nodes="result.standardSnapshot.graph.nodes" :edges="result.standardSnapshot.graph.edges" :editable="false"/></div></div></div><div v-if="result.grading" class="card"><div class="card-head"><b>关系逐项比对与订正建议</b></div><div class="card-body"><p v-for="(f,i) in result.grading.specialist?.feedback||[]" :key="i">{{f.message}}</p><p v-if="!(result.grading.specialist?.feedback?.length)" class="muted">{{result.grading.scoreStatus==='SPECIALIST_ONLY'?'本次专项没有偏差反馈。':'完整案例评分口径待确认。'}}</p><div v-for="d in result.grading.specialist?.dimensions||[]" :key="d.key" class="between"><span>{{d.label}} · {{d.applicable?d.detail:'不适用'}}</span><span>{{d.applicable?d.value:'—'}}</span></div><p class="t-xs muted digest">算法 {{result.scoringRuleVersion}} · 标准 {{result.standardVersionId}}</p></div></div><div v-if="result.teacherFeedback" class="card"><div class="card-head"><b>教师反馈记录</b></div><div class="card-body"><p v-for="f in result.teacherFeedback" :key="f.id">{{formatTime(f.createdAt)}} · {{f.comment}}</p><template v-if="data.teacherMode"><label>追加反馈<textarea class="textarea" v-model="feedback"></textarea></label><button class="btn btn-primary" :disabled="!feedback" @click="saveFeedback">保存新反馈</button></template></div></div></section></template>
 </fieldset>
</template>
<style scoped>.fields{border:0;margin:0;padding:0;min-width:0}.boundary{margin:20px 0}.t-h1{margin:6px 0}.row{display:flex;gap:8px;flex-wrap:wrap}.teaching-body{grid-template-columns:1.4fr 1fr;align-items:start}.card-head{gap:12px;flex-wrap:wrap}.panel{padding:14px;border:1px solid var(--border);border-radius:var(--r-md)}.item{padding:14px 0;border-bottom:1px solid var(--border)}.source-text{white-space:pre-wrap;line-height:1.9}.digest,.tbl td{overflow-wrap:anywhere}.empty{padding:35px 15px;text-align:center}.stack-3>label{display:block}.stack-3>label .input,.stack-3>label .select{margin-top:7px}.textarea{min-height:100px;width:100%}@media(max-width:1000px){.teaching-body{grid-template-columns:1fr}}@media(max-width:650px){.page-head{align-items:flex-start;flex-direction:column;gap:14px}}</style>
